class BoundedResourcePool:
    def __init__(self, size: int):
        self._semaphore = threading.Semaphore(size)
    def acquire(self) -> bool:
        return self._semaphore.acquire(timeout=5.0)
    def release(self) -> None:
        self._semaphore.release()
